# This function will filter signals based on the provided date range and strategy.
def run(context):
    date_range = context['inputs']['date_range']
    strategy_filter = context['inputs']['strategy_filter']
    filtered_signals = []
    # Loop through signals
    for signal in context['tables']['signals.signal_log']:
        # Check if signal is within date range and matches the strategy filter
        if signal['date_issued'] in date_range and signal['setup_class'] == strategy_filter:
            filtered_signals.append(signal)
    return {'filtered_signals': filtered_signals}
